function extractSetBody(text, name){
  const match = text.match(new RegExp('const\\s+' + name + '\\s*=\\s*new Set\\s*\\(\\s*\\[([\\s\\S]*?)\\]\\s*\\)\\s*;'));
  assert.ok(match, name + ' must be declared as an explicit Set');
  return match[1];
}

